<?php
require __DIR__.'/stock_issue_helpers.php';
use Tivoli\Service\StockIssueService;
use Tivoli\Repository\StockAvailability;
if(!class_exists(StockIssueService::class))throw new RuntimeException('Approved stock non-sale issue workflow is missing');
$si=new StockIssueService($a,$clock);
function ic(int $who,string $action,array $in=[],?string $key=null):array{global $si;return $si->execute($who,$action,$in,$key??sk());}
function iv(int $id,int $actor=0):array{global $si,$owner;$c=$si->detail($actor?:$owner,$id);return ['id'=>(string)$id,'version'=>$c['version'],'review_token'=>$c['review_token']];}
function report(int $x,array $more=[]):int{global $staff,$clock;return ic($staff,'report',$more+['extra_id'=>(string)$x,'kind'=>'damage','qty'=>'2.00','position'=>'held','actual_at'=>str_replace(' ','T',$clock),'comment'=>'Synthetic items secured separately','verified'=>'1'])['id'];}
function accept(int $id):array{global $owner;return ic($owner,'approve',iv($id)+['verified'=>'1','comment'=>'Original inventory facts verified']);}
function dispose(int $id):array{global $owner,$clock;return ic($owner,'dispose',iv($id)+['verified'=>'1','actual_at'=>str_replace(' ','T',$clock)]);}
function qty(int $x):string{global $r;return (string)$r->run('SELECT stock_qty FROM extras WHERE id=?',[$x])->fetchColumn();}
$cursor=(int)$r->run('SELECT COALESCE(MAX(id),0) FROM stock_movements')->fetchColumn();$original=$r->run('SELECT * FROM stock_movements WHERE id<=? ORDER BY id',[$cursor])->fetchAll();$money=[$r->run('SELECT * FROM payments ORDER BY id')->fetchAll(),$r->run('SELECT * FROM expenses ORDER BY id')->fetchAll()];
$x=sx('24.00');$id=report($x);sa(qty($x)==='24.00'&&StockAvailability::hold($r,$x)['held']===200,'report immediately holds stock without reducing recorded on hand');
sd(fn()=>ic($staff,'approve',iv($id)+['verified'=>'1']),'clerk cannot approve');sd(fn()=>ic($admin,'approve',iv($id)+['verified'=>'1']),'other administrator cannot approve');
accept($id);sa($si->detail($staff,$id)['status']==='approved'&&qty($x)==='24.00','approval alone records no physical outflow');
$in=iv($id)+['verified'=>'1','actual_at'=>str_replace(' ','T',$clock)];$key=sk();$result=ic($owner,'dispose',$in,$key);$again=ic($owner,'dispose',$in,$key);
sa($again['replayed']&&$again['event_id']===$result['event_id']&&qty($x)==='22.00','disposition retry returns durable result and deducts once');sa(StockAvailability::hold($r,$x)['held']===0&&$si->detail($staff,$id)['status']==='completed','actual disposal releases only its own hold');
sa((int)$r->run("SELECT COUNT(*) FROM stock_movements WHERE ref_type='stock_issue' AND ref_id=?",[$id])->fetchColumn()===1,'one original-linked out movement created');sd(fn()=>ic($owner,'dispose',$in,sk()),'fresh key cannot dispose completed source twice');sd(fn()=>ic($owner,'dispose',$in+['comment'=>'different'],$key),'same key cannot carry different details');
$id=report($x,['kind'=>'complimentary','qty'=>'1.25']);accept($id);dispose($id);sa(qty($x)==='20.75'&&$si->detail($staff,$id)['root']['data']['kind']==='complimentary','complimentary use preserves fractional quantities without a sale');
$id=report($x,['kind'=>'missing','position'=>'gone','qty'=>'0.75']);accept($id);sa(qty($x)==='20.00'&&$si->detail($staff,$id)['status']==='completed','verified already-gone stock posts with owner approval once');
$id=report($x);ic($owner,'return',iv($id)+['comment'=>'Clarify the storage location']);sa(StockAvailability::hold($r,$x)['held']===200,'returned report retains unsafe-stock hold');sd(fn()=>ic($other,'clarify',iv($id)+['comment'=>'Not my report']),'only original reporter clarifies');ic($staff,'clarify',iv($id,$staff)+['comment'=>'Labelled secured crate']);sa($si->detail($staff,$id)['status']==='pending'&&count($si->detail($staff,$id)['history'])===2,'clarification appends retained evidence and returns to owner');
sd(fn()=>report($x,['qty'=>'999.00']),'hold cannot exceed available stock');sd(fn()=>report($x,['qty'=>'0']),'zero quantity rejected');sd(fn()=>report($x,['qty'=>'-1']),'negative quantity rejected');sd(fn()=>report($x,['position'=>'held','kind'=>'missing']),'missing-and-held contradiction rejected');sd(fn()=>report($x,['actual_at'=>'2053-01-01T12:00']),'future actual time rejected');sd(fn()=>report($x,['verified'=>'0']),'report verification required');
$oldToken=iv($id);move($x,'-1.00');sd(fn()=>ic($owner,'approve',$oldToken+['verified'=>'1']),'intervening stock movement invalidates admin preview');
$y=sx('10.00');$count=start($staff,[$y]);countLine($staff,$count,$y,'8.00');sc($staff,'submit',sv($count,$staff)+['reasons'=>json_encode([$y=>['reason'=>'Damage','note'=>'Two broken units kept separately']]),'confirmed'=>'1']);approve($count);
$linked=report($y,['position'=>'counted','count_id'=>(string)$count]);accept($linked);dispose($linked);sa(qty($y)==='8.00'&&StockAvailability::hold($r,$y)['held']===0,'approved count-linked disposition has zero second quantity deduction');sa((int)$r->run("SELECT COUNT(*) FROM stock_movements WHERE ref_type='stock_issue' AND ref_id=?",[$linked])->fetchColumn()===0,'count disposition creates no duplicate movement');sd(fn()=>report($y,['position'=>'counted','count_id'=>(string)$count]),'approved count loss claimed only once');sd(fn()=>report($x,['position'=>'counted','count_id'=>(string)$count]),'count item mismatch rejected');
$z=sx('5.00');$rollback=report($z);accept($rollback);$in=iv($rollback)+['verified'=>'1','actual_at'=>'2052-08-05T14:00:00'];$key=sk();
$r->run("CREATE TRIGGER synthetic_issue_audit_fail BEFORE INSERT ON security_audit FOR EACH ROW BEGIN IF NEW.action='stockissue.dispose' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic required audit failure'; END IF; END");try{sd(fn()=>ic($owner,'dispose',$in,$key),'required audit failure rolls disposition back');}finally{$r->run('DROP TRIGGER synthetic_issue_audit_fail');}
sa(qty($z)==='5.00'&&StockAvailability::hold($r,$z)['held']===200&&!(bool)$r->run('SELECT event_id FROM finance_operations WHERE actor_id=? AND operation_key=?',[$owner,$key])->fetchColumn(),'rollback retains hold and no committed operation result');ic($owner,'dispose',$in,$key);sa(qty($z)==='3.00','same key succeeds once after rolled-back audit failure');
sa($r->run('SELECT * FROM stock_movements WHERE id<=? ORDER BY id',[$cursor])->fetchAll()===$original,'all preexisting stock movement rows unchanged');sa([$r->run('SELECT * FROM payments ORDER BY id')->fetchAll(),$r->run('SELECT * FROM expenses ORDER BY id')->fetchAll()]===$money,'stock issues create no sale payment or expense');
echo "TOTAL $n stock issue assertions passed.\n";
